


export type FulfillmentEventInput = { /** Controls buyer email handling. Omit or use send to send when recipient, template, and deduplication rules allow it. Use suppress when another system owns buyer messaging. */ "buyer_notification_behavior": "send" | "suppress"; /** Timeline entry creation timestamp. Format: date-time. */ "created_at"?: never; "current_status"?: never; "custom_details"?: Record<string, string>; "event_type": "status_changed" | "shipped" | "in_transit" | "out_for_delivery" | "delivered" | "delivery_attempted" | "tracking_updated" | "exception" | "returned" | "custom"; "external_event_id"?: string; "external_status"?: string; "external_system"?: string; "fulfillment_event_id"?: never; "fulfillment_id"?: never; "location_description"?: string; "message"?: string; /** Provider event timestamp. Format: date-time. */ "occurred_at"?: string | globalThis.Date; "order"?: never; "order_id"?: never; "package_id"?: never; "previous_status"?: never; "quantity_effect"?: never; "reason"?: never; /** The note supplied when this action was requested. */ "reason_message"?: never; /** Flint receive timestamp. Format: date-time. */ "received_at"?: never; "shipment_id"?: never; "subject_type"?: never; };
